def translate(text):
    text=text.replace('Localization diagnostic audit','Audyt lokalizacji watermarków')
    text=text.replace('510 OOF images, spatial alignment, foreground ranking, area bias, feature probes and reproducible evidence. No test predictions changed.',
                      '510 obrazów OOF: geometria STN, ranking pikseli, błędy powierzchni, sondy cech i odtwarzalne wyniki. Predykcje testowe bez zmian.')
    text=text.replace('Reused OOF predictions, not new independent validation.','Ponowna analiza OOF, nie nowy niezależny test.')
    text=text.replace('Matched linear probes; development confirmation includes the screening fold. Not a production-head improvement.',
                      'Porównanie identycznych sond liniowych; potwierdzenie obejmuje fold screeningowy. Nie jest to poprawa głowicy produkcyjnej.')
    for source in sorted(COPY, key=len, reverse=True):
        text = text.replace(source, COPY[source])
    return text


def localize(data):
    """Translate display fields only, leaving paths, IDs and numbers intact."""
    if isinstance(data, list):
        return [localize(value) for value in data]
    if isinstance(data, dict):
        return {key: translate(value) if key in {'title', 'note', 'detail', 'variant', 'protocol'}
                and isinstance(value, str) else localize(value) for key, value in data.items()}
    return data
